-- Cold-chain animal foods.
update public.content_entries
set metadata=jsonb_set(jsonb_set(metadata,'{safetyV2,storage}','{"title":"Soğuk saklama","items":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin."]}'::jsonb,true),'{safetyV2,verificationNeeded}','["Üretim veya kesim tarihi ve lot","Soğuk zincir kayıtları","Ambalaj ve son tüketim veya tavsiye edilen tüketim bilgisi"]'::jsonb,true),updated_at=timezone('utc',now())
where content_type='product_health' and status='published' and deleted_at is null and metadata#>>'{safetyV2,safetyClass}' in ('raw_milk','dairy','lamb','goat','poultry','fish','egg','animal_fat');

update public.content_entries set metadata=jsonb_set(jsonb_set(metadata,'{safetyV2,preparation}','{"title":"Hazırlama","items":["Çiğ eti diğer yiyeceklerden ve hazır tüketilecek ürünlerden ayrı tutun.","Bütün kuzu parçalarını en az 63°C iç sıcaklığa ulaştırın ve en az 3 dakika dinlendirin.","Kıyma veya kıyılmış kuzu karışımlarını en az 71°C iç sıcaklığa ulaştırın.","İç sıcaklığı gıda termometresiyle ölçün."]}'::jsonb,true),'{safetyV2,sources}','[{"authority":"USDA FSIS","title":"Lamb From Farm to Table","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/lamb-farm-table","topic":"Kuzu eti güvenli iç sıcaklıkları","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Refrigerator Thermometers – Cold Facts about Food Safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/refrigerator-thermometers-cold-facts-about-food-safety","topic":"Soğuk saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='lamb';

update public.content_entries set metadata=jsonb_set(jsonb_set(metadata,'{safetyV2,preparation}','{"title":"Hazırlama","items":["Çiğ eti diğer yiyeceklerden ayrı tutun.","Bütün oğlak veya keçi eti parçalarını en az 63°C iç sıcaklığa ulaştırın ve en az 3 dakika dinlendirin.","Kıyılmış veya öğütülmüş keçi etini en az 71°C iç sıcaklığa ulaştırın.","İç sıcaklığı gıda termometresiyle ölçün."]}'::jsonb,true),'{safetyV2,sources}','[{"authority":"USDA FSIS","title":"Goat From Farm to Table","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/goat-farm-table","topic":"Keçi veya oğlak eti güvenli iç sıcaklıkları","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Refrigerator Thermometers – Cold Facts about Food Safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/refrigerator-thermometers-cold-facts-about-food-safety","topic":"Soğuk saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='goat';

update public.content_entries set metadata=jsonb_set(jsonb_set(metadata,'{safetyV2,preparation}','{"title":"Hazırlama","items":["Çiğ kümes hayvanını hazır tüketilecek yiyeceklerden ayrı tutun.","Etin en kalın bölümünde en az 74°C iç sıcaklığa ulaşmasını sağlayın.","Güvenliği renk veya suyuna bakarak değil gıda termometresiyle doğrulayın."]}'::jsonb,true),'{safetyV2,sources}','[{"authority":"USDA FSIS","title":"Safe Minimum Internal Temperature Chart","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart","topic":"Kümes hayvanı güvenli iç sıcaklığı","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Refrigerator Thermometers – Cold Facts about Food Safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/refrigerator-thermometers-cold-facts-about-food-safety","topic":"Soğuk saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='poultry';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,preparation}','{"title":"Hazırlama","items":["Çiğ balığı diğer yiyeceklerden ayrı hazırlayın.","Balığın en kalın bölümünde en az 63°C iç sıcaklığa ulaşmasını sağlayın.","Kullanılan yüzey ve araçları işlem sonrasında temizleyin."]}'::jsonb,true),'{safetyV2,allergens}','{"known":["Balık"],"verifyLabel":true,"text":"Balık alerjeni içerir; tür ve etiket bilgisini kontrol edin."}'::jsonb,true),'{safetyV2,sources}','[{"authority":"USDA FSIS","title":"Safe Minimum Internal Temperature Chart","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart","topic":"Balık güvenli iç sıcaklığı","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Food Allergies","url":"https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/food-allergies","topic":"Balık alerjeni","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='fish';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,preparation}','{"title":"Hazırlama","items":["Yumurta ve yumurta içeren yemekleri en az 71°C iç sıcaklığa ulaştırın.","Çiğ yumurtayla temas eden yüzey ve araçları temizleyin."]}'::jsonb,true),'{safetyV2,allergens}','{"known":["Yumurta"],"verifyLabel":true,"text":"Yumurta alerjeni içerir; etiket ve çapraz bulaşma bilgisini kontrol edin."}'::jsonb,true),'{safetyV2,sources}','[{"authority":"USDA FSIS","title":"Safe Minimum Internal Temperature Chart","url":"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart","topic":"Yumurta güvenli iç sıcaklığı","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Food Allergies","url":"https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/food-allergies","topic":"Yumurta alerjeni","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='egg';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,warnings}','[{"code":"raw_milk","severity":"high","text":"Bu ürün kaydı çiğ veya pastörize edilmemiş süt olarak tanımlıdır. Çiğ süt Salmonella, E. coli, Listeria ve Campylobacter gibi zararlı mikroorganizmaları taşıyabilir."},{"code":"higher_risk_groups","severity":"high","text":"Hamileler, küçük çocuklar, yaşlılar ve bağışıklığı zayıf kişiler gıda kaynaklı hastalık açısından daha yüksek risk altındadır."}]'::jsonb,true),'{safetyV2,allergens}','{"known":["Süt"],"verifyLabel":true,"text":"Süt alerjeni içerir; ürün etiketini ve çapraz bulaşma bilgisini kontrol edin."}'::jsonb,true),'{safetyV2,verificationNeeded}','["Soğuk zincir sıcaklık kaydı","Sağım veya dolum tarihi ve lot","Mikrobiyolojik analiz ve yerel mevzuat uygunluğu"]'::jsonb,true),'{safetyV2,sources}','[{"authority":"FDA","title":"The Dangers of Raw Milk","url":"https://www.fda.gov/food/buy-store-serve-safe-food/dangers-raw-milk-unpasteurized-milk-can-pose-serious-health-risk","topic":"Çiğ süt riski","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Refrigerator Thermometers – Cold Facts about Food Safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/refrigerator-thermometers-cold-facts-about-food-safety","topic":"Soğuk saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='raw_milk';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,allergens}','{"known":["Süt"],"verifyLabel":true,"text":"Süt ve süt ürünleri alerjen olabilir; içerik ve alerjen etiketini kontrol edin."}'::jsonb,true),'{safetyV2,verificationNeeded}','["Pastörizasyon veya üretim yöntemi","Süt kaynağı ve alerjen etiketi","Soğuk zincir veya doğrulanmış raf ömrü"]'::jsonb,true),'{safetyV2,sources}','[{"authority":"FDA","title":"Food Allergies","url":"https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/food-allergies","topic":"Süt alerjeni","accessedAt":"2026-08-16"},{"authority":"FDA","title":"Refrigerator Thermometers – Cold Facts about Food Safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/refrigerator-thermometers-cold-facts-about-food-safety","topic":"Soğuk saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='dairy';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,storage}','{"title":"Saklama","items":["Ambalajı kapalı, kuru ve doğrudan güneş almayan yerde saklayın.","Kristalleşme tek başına bozulma göstergesi değildir; lot ve etiket bilgisini kontrol edin."]}'::jsonb,true),'{safetyV2,warnings}','[{"code":"honey_under_12_months","severity":"high","text":"12 aydan küçük çocuklara bal vermeyin; bebek botulizmi riski vardır."},{"code":"no_medical_claim","severity":"info","text":"Bal bir gıdadır; hastalık tedavisi veya önlenmesi iddiasıyla sunulmaz."}]'::jsonb,true),'{safetyV2,sources}','[{"authority":"CDC","title":"Foods and Drinks to Avoid or Limit – Honey before 12 months","url":"https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/foods-and-drinks-to-avoid-or-limit.html","topic":"Bebeklerde bal ve botulizm","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='honey';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,storage}','{"title":"Saklama","items":["Taze mantarı temiz buzdolabında 4°C veya altında saklayın.","Ambalaj, hasat tarihi ve tür doğrulama kaydını kontrol edin."]}'::jsonb,true),'{safetyV2,preparation}','{"title":"Hazırlama","items":["Yalnız güvenilir uzman tarafından türü doğrulanmış yabani mantarı kullanın.","Pişirme, yanlış tanımlanmış zehirli bir türü güvenli hale getirme garantisi değildir.","Hasat veya tür doğrulama kaydı yoksa tüketmeyin."]}'::jsonb,true),'{safetyV2,warnings}','[{"code":"expert_identification","severity":"high","text":"Yabani mantarlar zehirli benzerleriyle karıştırılabilir. Uzman tür doğrulaması olmadan tüketmeyin."},{"code":"cooking_not_guarantee","severity":"high","text":"Bazı yabani mantar toksinleri pişirmeyle güvenilir biçimde ortadan kalkmaz."}]'::jsonb,true),'{safetyV2,verificationNeeded}','["Türün uzman tarafından doğrulanması","Hasat yeri, tarihi ve lot","Taze veya kuru ürün formu ve saklama koşulu"]'::jsonb,true),'{safetyV2,sources}','[{"authority":"FDA","title":"Investigation of Illnesses: Morel Mushrooms","url":"https://www.fda.gov/food/outbreaks-foodborne-illness/investigation-illnesses-morel-mushrooms-may-2023","topic":"Yabani ve kuzu göbeği mantarı güvenliği","accessedAt":"2026-08-16"},{"authority":"CDC","title":"Health Care Utilization and Outcomes Associated with Accidental Poisonous Mushroom Ingestions","url":"https://www.cdc.gov/mmwr/volumes/70/wr/mm7010a1.htm","topic":"Yabani mantar zehirlenmesi","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='wild_mushroom';

update public.content_entries set metadata=jsonb_set(jsonb_set(jsonb_set(metadata,'{safetyV2,storage}','{"title":"Saklama","items":["Hasarlı veya çürük kısımları ayırın.","Çilek ve benzeri hassas ürünleri temiz buzdolabında 4°C veya altında saklayın; diğer ürünlerde ürün etiketindeki saklama talimatını izleyin."]}'::jsonb,true),'{safetyV2,preparation}','{"title":"Hazırlama","items":["Hazırlamadan önce ellerinizi yıkayın.","Ürünü yemeden veya kesmeden önce temiz akan su altında durulayın.","Sabun, deterjan veya çamaşır suyu ile yıkamayın.","Çiğ et, balık veya kümes hayvanı için kullanılan yüzeylerden ayrı tutun."]}'::jsonb,true),'{safetyV2,sources}','[{"authority":"FDA","title":"Selecting and Serving Produce Safely","url":"https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-produce-safely","topic":"Taze ürün yıkama ve saklama","accessedAt":"2026-08-16"}]'::jsonb,true),updated_at=timezone('utc',now()) where metadata#>>'{safetyV2,safetyClass}'='fresh_produce';